function setSettingsStatusChip(id, text, tone = '') {
  const el = $(id);
  if (!el) return;
  el.textContent = text;
  el.dataset.tone = tone;
}

function setSettingsNotice(text = '', tone = 'warn') {
  const el = $('settings-page-notice');
  if (!el) return;
  el.textContent = String(text || '');
  el.dataset.tone = tone;
  el.hidden = !text;
}

function hardwareDeviceText(item = {}) {
  const devices = item.devices && typeof item.devices === 'object' ? item.devices : {};
  const paths = Object.values(devices)
    .filter((device) => device && device.path)
    .map((device) => `${device.present ? '●' : '○'} ${device.path}`);
  return paths.join(' · ') || 'No device information';
}

function hardwareChip(item = {}) {
  const status = String(item.state || 'unknown');
  if (item.responding || status === 'ready') return { text: status === 'busy' ? 'busy' : 'responding', tone: status === 'busy' ? 'running' : 'ok' };
  if (status === 'waiting') return { text: 'waiting', tone: 'running' };
  if (status === 'incomplete') return { text: 'incomplete', tone: 'warn' };
  if (status === 'unresponsive') return { text: 'not responding', tone: 'error' };
  if (status === 'unreachable' || status === 'head-unavailable') return { text: 'head offline', tone: 'warn' };
  if (status === 'missing') return { text: 'not connected', tone: 'error' };
  if (item.device_present || item.present) return { text: 'not responding', tone: 'error' };
  return { text: 'unavailable', tone: 'warn' };
}

function renderHardwareSettings(hardware = {}) {
  const puddleduck = hardware.puddleduck || {};
  const quackhead = hardware.quackhead || {};
  state.hardware.puddleduck = puddleduck;
  state.hardware.quackhead = quackhead;

  const bodyChip = hardwareChip(puddleduck);
  setSettingsStatusChip('puddleduck-hardware-chip', bodyChip.text, bodyChip.tone);
  setText('puddleduck-hardware-summary', puddleduck.message || 'PuddleDuck status is unavailable.');
  setText('puddleduck-hardware-devices', hardwareDeviceText(puddleduck));

  const headChip = hardwareChip(quackhead);
  setSettingsStatusChip('quackhead-hardware-chip', headChip.text, headChip.tone);
  setText('quackhead-hardware-summary', quackhead.message || 'QuackHead status is unavailable.');
  setText('quackhead-hardware-devices', hardwareDeviceText(quackhead));
}

function setDuckHardwareNoticeDismissed(dismissed) {
  state.hardware.noticeDismissed = Boolean(dismissed);
  try {
    if (dismissed) sessionStorage.setItem('puddleduck.hardware.notice.dismissed', '1');
    else sessionStorage.removeItem('puddleduck.hardware.notice.dismissed');
  } catch { /* session storage is optional */ }
}

function duckHardwareNoticeTitle(item = {}) {
  const status = String(item.state || 'unknown');
  if (status === 'missing') return 'PuddleDuck controller not detected';
  if (status === 'waiting') return 'Waiting for PuddleDuck telemetry';
  if (status === 'incomplete') return 'PuddleDuck USB enumeration is incomplete';
  return 'PuddleDuck controller not responding';
}

function updateDuckHardwareNotice(item = {}, { notify = false } = {}) {
  state.hardware.puddleduck = item;
  const responding = Boolean(item.responding);
  const notice = $('duck-hardware-notice');
  if (responding) {
    if (notice) notice.hidden = true;
    state.hardware.warned = false;
    setDuckHardwareNoticeDismissed(false);
    return;
  }

  setText('duck-hardware-notice-title', duckHardwareNoticeTitle(item));
  setText('duck-hardware-notice-message', item.message || 'Live telemetry and motor controls are unavailable.');
  if (notice) notice.hidden = state.hardware.noticeDismissed;
  if (notify && !state.hardware.warned && !state.hardware.noticeDismissed) {
    toast(item.message || 'PuddleDuck controller is not responding.', 7000);
    state.hardware.warned = true;
  }
}

function dismissDuckHardwareNotice() {
  setDuckHardwareNoticeDismissed(true);
  const notice = $('duck-hardware-notice');
  if (notice) notice.hidden = true;
}

async function loadBodyHardwareStatus({ notify = false } = {}) {
  const response = await api('/api/hardware');
  updateDuckHardwareNotice(response.puddleduck || {}, { notify });
  return response;
}

function startHardwareStatusPolling() {
  clearInterval(state.hardware.pollTimer);
  state.hardware.pollTimer = 0;
  loadBodyHardwareStatus({ notify: true }).catch((error) => {
    console.warn('PuddleDuck hardware status unavailable', error);
  });
  state.hardware.pollTimer = window.setInterval(() => {
    loadBodyHardwareStatus({ notify: true }).catch(() => {});
  }, 5000);
}

function bodyWifiProfiles() {
  const profiles = state.settings.data?.body_wifi?.profiles;
  return Array.isArray(profiles) ? profiles : [];
}

function renderBodyWifi(body = {}) {
  const current = body.current || {};
  const wpa3Active = Boolean(current.wpa3_active);
  if (wpa3Active) {
    setSettingsStatusChip('body-wifi-status-chip', 'WPA3 blocked', 'error');
  } else if (current.active) {
    setSettingsStatusChip('body-wifi-status-chip', 'connected', 'ok');
  } else if (!body.available) {
    setSettingsStatusChip('body-wifi-status-chip', 'unavailable', 'error');
  } else {
    setSettingsStatusChip('body-wifi-status-chip', 'offline', 'warn');
  }

  const currentParts = [];
  if (current.ssid) currentParts.push(current.ssid);
  if (current.security) currentParts.push(current.security);
  if (wpa3Active) currentParts.push('unsupported WPA3');
  else if (current.transition) currentParts.push('WPA2 enforced');
  setText('body-wifi-current', currentParts.join(' · ') || 'Not connected');
  const interfaceParts = [];
  if (current.device) interfaceParts.push(current.device);
  if (Array.isArray(current.addresses) && current.addresses.length) interfaceParts.push(current.addresses.join(', '));
  setText('body-wifi-address', interfaceParts.join(' · ') || '–');
  setText('body-wifi-signal', Number.isFinite(Number(current.signal)) ? `${Math.round(Number(current.signal))}%` : '–');

  const saveNetwork = $('btn-save-body-wifi');
  if (saveNetwork) saveNetwork.disabled = !body.available;

  const helperMessage = $('body-wifi-helper-message');
  if (helperMessage) {
    const policyMessage = wpa3Active
      ? (current.warning || 'WPA3 is not supported on this robot. Use WPA2 or WPA2/WPA3 transition mode.')
      : '';
    const message = policyMessage || body.message || '';
    helperMessage.hidden = !message;
    helperMessage.textContent = message;
    helperMessage.dataset.tone = policyMessage ? 'error' : (body.available ? 'warn' : 'error');
  }

  const list = $('body-wifi-profile-list');
  if (!list) return;
  const profiles = Array.isArray(body.profiles) ? body.profiles : [];
  if (!profiles.length) {
    const unavailable = body.message
      ? `Saved networks are unavailable: ${escapeHtml(body.message)}`
      : 'Saved networks are unavailable until the overlay command and sudo rule are installed.';
    list.innerHTML = `<div class="wifi-profile-empty muted">${body.available ? 'No saved body Wi-Fi networks.' : unavailable}</div>`;
    return;
  }

  list.innerHTML = profiles.map((profile) => {
    const details = [
      `priority ${Number(profile.priority ?? 50)}`,
      profile.open ? 'open' : 'secured',
      profile.hidden ? 'hidden' : 'broadcast',
    ];
    if (profile.visible) details.push(`${Number(profile.signal || 0)}% signal`);
    if (profile.wpa3_only) details.push('WPA3 only · blocked');
    else if (profile.transition) details.push('WPA2 enforced');
    if (profile.method && profile.method !== 'auto') details.push(profile.method);
    return `
      <div class="wifi-profile-row" data-active="${profile.active ? 'true' : 'false'}" data-security-mode="${escapeHtml(profile.security_mode || '')}">
        <div class="wifi-profile-main">
          <div class="wifi-profile-name">
            <strong>${escapeHtml(profile.ssid || '')}</strong>
            ${profile.active && !profile.wpa3_only ? '<span class="settings-status-chip" data-tone="ok">connected</span>' : ''}
            ${profile.wpa3_only ? '<span class="settings-status-chip" data-tone="error">WPA3 blocked</span>' : ''}
            ${profile.transition && !profile.active ? '<span class="settings-status-chip" data-tone="warn">WPA2 only</span>' : ''}
            ${profile.visible && !profile.active && !profile.wpa3_only && !profile.transition ? '<span class="settings-status-chip" data-tone="running">available</span>' : ''}
          </div>
          <span class="muted">${escapeHtml(details.join(' · '))}</span>
        </div>
        <div class="wifi-profile-actions">
          <button type="button" data-wifi-edit="${escapeHtml(profile.ssid || '')}">Edit</button>
          <button type="button" class="danger" data-wifi-delete="${escapeHtml(profile.ssid || '')}">Delete</button>
        </div>
      </div>`;
  }).join('');

  list.querySelectorAll('[data-wifi-edit]').forEach((button) => {
    button.addEventListener('click', () => editBodyWifiProfile(button.dataset.wifiEdit || ''));
  });
  list.querySelectorAll('[data-wifi-delete]').forEach((button) => {
    button.addEventListener('click', () => {
      deleteBodyWifiProfile(button.dataset.wifiDelete || '').catch((error) => toast(error.message, 6200));
    });
  });
}

function renderHeadSettings(head = {}) {
  const service = head.settings_service || {};
  const accessPoint = head.access_point || {};
  setSettingsStatusChip(
    'head-settings-status-chip',
    service.reachable ? 'connected' : 'offline',
    service.reachable ? 'ok' : 'warn',
  );
  setText('head-settings-status', service.reachable ? `${head.host || 'bdx-head'}:${service.port || 8081}` : (service.message || 'Unavailable'));
  const suffixParts = [];
  if (accessPoint.mac) suffixParts.push(accessPoint.mac);
  if (accessPoint.mac_suffix) suffixParts.push(`suffix ${accessPoint.mac_suffix}`);
  setText('head-ap-suffix', suffixParts.join(' · ') || '–');
  setText('head-ap-current', accessPoint.ssid || '–');

  const name = $('head-ap-name');
  if (name) name.value = accessPoint.name || 'BD-X Duckling';
  const password = $('head-ap-password');
  if (password) {
    password.value = '';
    password.placeholder = accessPoint.password_set ? 'Saved — leave blank to keep' : 'Enter an 8–63 character password';
  }
  setText(
    'head-ap-password-help',
    accessPoint.password_set
      ? 'A password is stored on the head. Leave this field blank to keep it.'
      : 'No access-point password is currently stored.',
  );
  const save = $('btn-save-head-ap');
  if (save) save.disabled = !service.reachable;

  const proxy = head.proxy || {};
  setSettingsStatusChip('head-proxy-status-chip', proxy.reachable ? 'reachable' : 'offline', proxy.reachable ? 'ok' : 'warn');
  setText('head-proxy-status', proxy.reachable ? `${head.host || 'bdx-head'}:${proxy.port || 8080} forwards to the body` : (proxy.message || 'Unavailable'));
}

function renderAccessPaths(paths = {}) {
  setText('access-body-ethernet', paths.body_ethernet || '192.168.50.2:8080');
  setText('access-head-ethernet', paths.head_ethernet || '192.168.50.1:8080');
  setText('access-head-ap', paths.head_access_point || '192.168.51.1:8080');
  setText('access-usb', paths.usb || '192.168.55.1:8080');
}

function resetBodyWifiForm() {
  const form = $('body-wifi-form');
  form?.reset();
  const editing = $('body-wifi-editing-ssid');
  if (editing) editing.value = '';
  state.settings.editingSsid = '';
  const priority = $('body-wifi-priority');
  if (priority) priority.value = '50';
  const save = $('btn-save-body-wifi');
  if (save) save.textContent = 'Add network';
  const cancel = $('btn-cancel-body-wifi-edit');
  if (cancel) cancel.hidden = true;
  const password = $('body-wifi-password');
  if (password) {
    password.disabled = false;
    password.value = '';
    password.placeholder = 'Enter password';
  }
  setText('body-wifi-password-help', 'Enter a password for a new secured network.');
}

function updateBodyWifiPasswordState() {
  const open = Boolean($('body-wifi-open')?.checked);
  const password = $('body-wifi-password');
  if (!password) return;
  password.disabled = open;
  if (open) password.value = '';
}

function editBodyWifiProfile(ssid) {
  const profile = bodyWifiProfiles().find((item) => String(item.ssid || '') === String(ssid || ''));
  if (!profile) return;
  state.settings.editingSsid = String(profile.ssid || '');
  const editing = $('body-wifi-editing-ssid');
  if (editing) editing.value = state.settings.editingSsid;
  const name = $('body-wifi-ssid');
  if (name) name.value = profile.ssid || '';
  const priority = $('body-wifi-priority');
  if (priority) priority.value = String(profile.priority ?? 50);
  const hidden = $('body-wifi-hidden');
  if (hidden) hidden.checked = Boolean(profile.hidden);
  const open = $('body-wifi-open');
  if (open) open.checked = Boolean(profile.open);
  const password = $('body-wifi-password');
  if (password) {
    password.value = '';
    password.placeholder = profile.open ? 'Not used for an open network' : (profile.password_set ? 'Saved — leave blank to keep' : 'Enter password');
  }
  setText(
    'body-wifi-password-help',
    profile.open
      ? 'This saved network is open.'
      : (profile.password_set ? 'A password is saved. Leave blank to keep it.' : 'No password is saved.'),
  );
  const save = $('btn-save-body-wifi');
  if (save) save.textContent = 'Update network';
  const cancel = $('btn-cancel-body-wifi-edit');
  if (cancel) cancel.hidden = false;
  updateBodyWifiPasswordState();
  $('body-wifi-form')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function renderSettingsJob(job = {}) {
  state.settings.job = job || { state: 'idle' };
  const panel = $('settings-job-panel');
  if (!panel) return;
  const status = String(job.state || 'idle');
  panel.hidden = status === 'idle';
  const names = { body_wifi: 'Body Wi-Fi', head_ap: 'Head access point' };
  setText('settings-job-title', names[job.component] || 'Settings');
  setText('settings-job-message', job.message || 'Waiting…');
  setSettingsStatusChip('settings-job-state', status, status === 'complete' ? 'ok' : status === 'error' ? 'error' : 'running');
  const progress = $('settings-job-progress');
  if (progress) {
    if (status === 'running') progress.removeAttribute('value');
    else progress.value = status === 'complete' ? 1 : 0;
  }

  clearTimeout(state.settings.jobTimer);
  state.settings.jobTimer = 0;
  if (status === 'running') {
    state.settings.jobTimer = setTimeout(async () => {
      try {
        const response = await api('/api/settings/job');
        renderSettingsJob(response.job || {});
        if (response.job?.state && response.job.state !== 'running') {
          await loadSettingsTab({ quiet: true });
        }
      } catch (error) {
        setText('settings-job-message', error.message || 'Unable to read settings status.');
      }
    }, 900);
  }
}

function setSecurityMessage(id, text = '', tone = '') {
  const element = $(id);
  if (!element) return;
  element.textContent = String(text || '');
  element.dataset.tone = tone;
  element.hidden = !text;
}

function renderSecuritySettings(response = {}) {
  const security = response.security || {};
  const browser = security.browser || {};
  const account = security.duck_account || response.duck_account || {};
  state.settings.security.browser = browser;
  state.settings.security.duckAccount = account;

  const configured = Boolean(browser.configured);
  setSettingsStatusChip(
    'browser-auth-status-chip',
    configured ? 'protected' : 'not configured',
    configured ? 'ok' : 'warn',
  );
  setText(
    'browser-auth-summary',
    configured
      ? `This browser is authenticated. Sessions are remembered for ${browser.session_days || 180} days.`
      : 'Authentication is currently disabled. Set a browser password before using the robot on an untrusted network.',
  );
  const currentRow = $('browser-current-password-row');
  if (currentRow) currentRow.hidden = !configured;
  const current = $('browser-current-password');
  if (current && !configured) current.value = '';
  const save = $('btn-save-browser-password');
  if (save) save.textContent = configured ? 'Change browser password' : 'Set browser password';
  const logout = $('btn-browser-logout');
  if (logout) logout.hidden = !configured;

  const bodyReady = Boolean(account.body?.ok);
  const headReady = Boolean(account.head?.ok || account.head?.available);
  const available = Boolean(account.available && bodyReady && headReady && configured);
  if (!configured) {
    setSettingsStatusChip('duck-account-status-chip', 'locked', 'warn');
  } else {
    setSettingsStatusChip('duck-account-status-chip', available ? 'ready' : 'unavailable', available ? 'ok' : 'error');
  }
  const details = [];
  details.push(`Body: ${bodyReady ? 'ready' : (account.body?.message || 'unavailable')}`);
  details.push(`Head: ${headReady ? 'ready' : (account.head?.message || 'unavailable')}`);
  setText(
    'duck-account-summary',
    configured ? details.join(' · ') : 'Set a browser password first. Linux account changes are disabled while browser authentication is open.',
  );
  const duckButton = $('btn-save-duck-password');
  if (duckButton) duckButton.disabled = !available || state.settings.security.busy;
}

async function saveBrowserPassword() {
  const current = $('browser-current-password')?.value || '';
  const next = $('browser-new-password')?.value || '';
  const confirmPassword = $('browser-confirm-password')?.value || '';
  if (next !== confirmPassword) throw new Error('New browser passwords do not match.');
  if (next.length < 8) throw new Error('Browser password must contain at least 8 characters.');
  const button = $('btn-save-browser-password');
  if (button) button.disabled = true;
  setSecurityMessage('browser-password-message', 'Saving browser password…');
  try {
    const response = await api('/api/settings/browser-password', {
      method: 'POST',
      body: JSON.stringify({ current_password: current, new_password: next }),
    });
    $('browser-password-form')?.reset();
    state.auth = { ...state.auth, ...(response.authentication || {}), configured: true, authenticated: true };
    if (state.eventSource) startEvents();
    setSecurityMessage('browser-password-message', response.message || 'Browser password saved.', 'ok');
    toast(response.message || 'browser password saved', 5000);
    await loadSettingsTab({ quiet: true });
  } finally {
    if (button) button.disabled = false;
  }
}

async function saveDuckPassword() {
  const next = $('duck-new-password')?.value || '';
  const confirmPassword = $('duck-confirm-password')?.value || '';
  if (next !== confirmPassword) throw new Error('Linux passwords do not match.');
  if (next.length < 8) throw new Error('Linux password must contain at least 8 characters.');
  if (!window.confirm('Change the Linux duck account password on both the head and body Orins? Future SSH logins must use the new password.')) return;
  const button = $('btn-save-duck-password');
  state.settings.security.busy = true;
  if (button) button.disabled = true;
  setSecurityMessage('duck-password-message', 'Updating the duck account on both Orins…');
  try {
    const response = await api('/api/settings/duck-password', {
      method: 'POST',
      body: JSON.stringify({ password: next }),
    });
    $('duck-password-form')?.reset();
    setSecurityMessage('duck-password-message', response.message || 'Linux password updated.', 'ok');
    toast(response.message || 'Linux duck password updated', 5000);
  } finally {
    state.settings.security.busy = false;
    if (button) button.disabled = false;
  }
}

function renderDuckHostnames(hostnames = {}) {
  const external = String(hostnames.external_hostname || '').trim();
  setText('duck-external-hostname', external || (hostnames.message ? 'unavailable' : 'duckling.local'));
  const externalElement = $('duck-external-hostname');
  if (externalElement) externalElement.title = String(hostnames.message || 'External Avahi/mDNS name published by the body Orin.');
  setText('duck-system-hostname', String(hostnames.system_hostname || hostnames.mdns_label || 'duckling'));
  const aliases = Array.isArray(hostnames.internal_host_aliases)
    ? hostnames.internal_host_aliases.filter(Boolean).join(', ')
    : 'bdx-body, bdx-head';
  setText('duck-internal-aliases', aliases || 'bdx-body, bdx-head');

  const httpsUrl = String(hostnames.https_url || (external ? `https://${external}/` : '')).trim();
  const certificateAvailable = Boolean(hostnames.certificate_available);
  const certificateButton = $('btn-download-https-ca');
  if (certificateButton) certificateButton.disabled = !certificateAvailable;
  setText(
    'duck-https-status',
    httpsUrl
      ? `${httpsUrl}${certificateAvailable ? ' · local CA ready' : ' · local CA certificate is still being prepared'}`
      : 'HTTPS is unavailable until Caddy is installed.',
  );
}

function openbdxSlug(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 100);
}

function openbdxStatusMessage(data = {}) {
  const profile = data.profile || {};
  const who = profile.display_name || (profile.handle ? `@${profile.handle}` : 'OpenBDX account');
  if (data.connected) {
    return `Connected to ${who} as ${data.display_name || 'this duck'} · ${data.origin}`;
  }
  if (data.pending?.user_code) return `Waiting for approval of ${data.pending.user_code}.`;
  if (data.paired) {
    return `Authorized for ${who}, but this duck has not finished registering · ${data.origin}`;
  }
  return `Not connected · ${data.origin || 'https://openbdx.org'}`;
}

function renderOpenBDXStatus(data = {}) {
  state.settings.openbdx.data = data;
  const connected = Boolean(data.connected);
  const paired = Boolean(data.paired || connected);
  const pending = Boolean(data.pending?.user_code);
  const chip = $('openbdx-status-chip');
  if (chip) {
    chip.textContent = connected ? 'connected' : paired ? 'registration pending' : pending ? 'waiting' : 'not connected';
    chip.dataset.tone = connected ? 'ok' : (paired || pending) ? 'warn' : '';
  }
  const environmentBadge = $('openbdx-environment-badge');
  if (environmentBadge) {
    let staging = false;
    try {
      staging = new URL(String(data.origin || 'https://openbdx.org')).hostname.startsWith('staging.');
    } catch (_error) {
      staging = false;
    }
    environmentBadge.hidden = !staging;
    environmentBadge.textContent = staging ? 'STAGING' : '';
  }
  setText('openbdx-account-summary', openbdxStatusMessage(data));
  const pairing = $('openbdx-pairing');
  if (pairing) pairing.hidden = !pending;
  setText('openbdx-user-code', pending ? data.pending.user_code : '');
  const link = $('openbdx-verification-link');
  if (link) {
    link.href = pending ? String(data.pending.verification_uri_complete || data.pending.verification_uri || '#') : '#';
  }
  const connect = $('btn-openbdx-connect');
  const sync = $('btn-openbdx-sync');
  const disconnect = $('btn-openbdx-disconnect');
  if (connect) {
    connect.disabled = paired || pending || state.settings.openbdx.busy;
    connect.textContent = pending ? 'Waiting for approval…' : connected ? 'Connected' : paired ? 'Authorized' : 'Connect';
  }
  if (sync) sync.disabled = !paired || state.settings.openbdx.busy;
  if (disconnect) disconnect.disabled = !(paired || pending) || state.settings.openbdx.busy;
  const message = $('openbdx-message');
  if (message) {
    message.textContent = data.last_error || data.busy || (data.last_sync_at ? `Last synchronized ${new Date(data.last_sync_at).toLocaleString()}` : '');
    message.dataset.tone = data.last_error ? 'error' : '';
  }
  updatePolicyButtons();
  updateEmoteButtons();
  clearTimeout(state.settings.openbdx.timer);
  if (pending || paired) {
    state.settings.openbdx.timer = window.setTimeout(() => loadOpenBDXStatus({ quiet: true }).catch(() => {}), pending ? 2500 : 15000);
  }
}

async function loadOpenBDXStatus({ quiet = false } = {}) {
  if (state.settings.openbdx.loading) return state.settings.openbdx.data;
  state.settings.openbdx.loading = true;
  try {
    const data = await api('/api/openbdx/status');
    renderOpenBDXStatus(data || {});
    if (!quiet) toast('OpenBDX status refreshed');
    return data;
  } finally {
    state.settings.openbdx.loading = false;
  }
}

async function connectOpenBDX() {
  state.settings.openbdx.busy = true;
  renderOpenBDXStatus(state.settings.openbdx.data || {});
  try {
    const displayName = String(state.settings.data?.settings?.duck_name || document.title.split(' · ')[0] || 'PuddleDuck');
    const data = await api('/api/openbdx/pair', { method: 'POST', body: JSON.stringify({ display_name: displayName }) });
    renderOpenBDXStatus(data || {});
    const url = data?.pending?.verification_uri_complete;
    if (url) window.open(url, '_blank', 'noopener,noreferrer');
    toast(`Approve code ${data?.pending?.user_code || ''} on OpenBDX.`, 7200);
  } finally {
    state.settings.openbdx.busy = false;
    renderOpenBDXStatus(state.settings.openbdx.data || {});
  }
}

async function syncOpenBDX() {
  state.settings.openbdx.busy = true;
  renderOpenBDXStatus(state.settings.openbdx.data || {});
  try {
    const data = await api('/api/openbdx/sync', { method: 'POST', body: '{}' });
    renderOpenBDXStatus(data || {});
    toast('OpenBDX synchronization requested.');
  } finally {
    state.settings.openbdx.busy = false;
    window.setTimeout(() => loadOpenBDXStatus({ quiet: true }).catch(() => {}), 1000);
  }
}

async function disconnectOpenBDX() {
  if (!window.confirm('Disconnect this duck from OpenBDX? Pending installations will be canceled and a new code will be required to reconnect.')) return;
  state.settings.openbdx.busy = true;
  try {
    const data = await api('/api/openbdx/connection', { method: 'DELETE', body: '{}' });
    renderOpenBDXStatus(data || {});
    toast('Duck disconnected from OpenBDX.');
  } finally {
    state.settings.openbdx.busy = false;
    renderOpenBDXStatus(state.settings.openbdx.data || {});
  }
}

function openOpenBDXPublishDialog(kind) {
  const dialog = $('openbdx-publish-dialog');
  const isEmote = kind === 'emote';
  const item = isEmote ? selectedEmote() : selectedPolicy();
  if (!item) throw new Error(`select ${isEmote ? 'an emote' : 'a policy'} first`);
  if (!state.settings.openbdx.data?.connected) throw new Error('connect this duck to OpenBDX first');
  if (isEmote && (item.read_only || !item.editable)) throw new Error('only editable user Duckmation emotes can be published');
  if (!isEmote && !/\.onnx$/i.test(item.name || '')) throw new Error('only ONNX policies can be published');
  const title = isEmote ? String(item.name || item.filename || '').replace(/[_-]+/g, ' ') : String(item.name || '').replace(/\.onnx$/i, '').replace(/[_-]+/g, ' ');
  $('openbdx-publish-kind').value = kind;
  $('openbdx-publish-filename').value = String(item.filename || item.name || '');
  $('openbdx-publish-title-input').value = title.replace(/\b\w/g, (letter) => letter.toUpperCase());
  $('openbdx-publish-slug').value = openbdxSlug(title);
  $('openbdx-publish-summary').value = isEmote
    ? String(item.description || `An emote created on ${state.settings.openbdx.data?.display_name || 'PuddleDuck'}.`)
    : `An ONNX policy published from ${state.settings.openbdx.data?.display_name || 'PuddleDuck'}.`;
  $('openbdx-publish-description').value = isEmote ? String(item.description || '') : '';
  $('openbdx-publish-version').value = '1.0.0';
  $('openbdx-publish-license').value = isEmote ? 'CC-BY-4.0' : 'Apache-2.0';
  $('openbdx-publish-visibility').value = 'public';
  $('openbdx-publish-tags').value = isEmote ? 'emote, duckmation' : 'policy, onnx';
  $('openbdx-publish-changelog').value = 'Published from PuddleDuck.';
  $('openbdx-publish-remixes').checked = true;
  setText('openbdx-publish-source', `${isEmote ? 'Emote' : 'Policy'} · ${item.filename || item.name}`);
  const message = $('openbdx-publish-message');
  if (message) { message.hidden = true; message.textContent = ''; }
  dialog?.showModal();
}

function closeOpenBDXPublishDialog() {
  $('openbdx-publish-dialog')?.close();
}

async function submitOpenBDXPublication(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const kind = String($('openbdx-publish-kind').value || '');
  const filename = String($('openbdx-publish-filename').value || '');
  const submit = $('btn-openbdx-publish-submit');
  const message = $('openbdx-publish-message');
  const formData = new FormData(form);
  const metadata = Object.fromEntries(formData.entries());
  metadata.allow_remixes = $('openbdx-publish-remixes').checked;
  metadata.tags = String(metadata.tags || '').split(',').map((tag) => tag.trim()).filter(Boolean);
  if (submit) submit.disabled = true;
  state.settings.openbdx.busy = true;
  updatePolicyButtons();
  updateEmoteButtons();
  if (message) { message.hidden = false; message.dataset.tone = ''; message.textContent = `Uploading ${filename} to OpenBDX…`; }
  try {
    const response = await api(`/api/openbdx/publish/${encodeURIComponent(kind)}`, {
      method: 'POST',
      body: JSON.stringify({ filename, metadata }),
    });
    const version = response?.publication?.version?.version || {};
    const work = response?.publication?.version?.work || {};
    closeOpenBDXPublishDialog();
    toast(`Published ${work.title || filename}${version.version_label ? ` ${version.version_label}` : ''} to OpenBDX.`, 7200);
    if (kind === 'emote') await loadEmoteSettings({ quiet: true });
  } catch (error) {
    if (message) { message.hidden = false; message.dataset.tone = 'error'; message.textContent = error.message; }
  } finally {
    if (submit) submit.disabled = false;
    state.settings.openbdx.busy = false;
    updatePolicyButtons();
    updateEmoteButtons();
  }
}

function renderSettingsSnapshot(response = {}) {
  const apiVersion = Number(response.settings_api_version || 0);
  if (apiVersion !== SETTINGS_API_VERSION) {
    throw new Error(
      `Settings frontend/backend mismatch (browser expects v${SETTINGS_API_VERSION}, server reported ${apiVersion || "legacy"}). `
      + 'Rebuild and reinstall the PuddleDuck runtime wheel, then reload this page.'
    );
  }
  state.settings.data = response;
  const identity = response.settings || {};
  const name = $('duck-name');
  if (name) name.value = identity.duck_name || '';
  document.title = identity.duck_name ? `${identity.duck_name} · PuddleDuck` : 'PuddleDuck';
  renderDuckHostnames(response.hostnames || {});
  renderBodyWifi(response.body_wifi || {});
  renderHeadSettings(response.head || {});
  renderHardwareSettings(response.hardware || {});
  renderAccessPaths(response.access_paths || {});
  renderSecuritySettings(response);
  renderSettingsJob(response.job || {});
}

async function loadSettingsTab({ quiet = false } = {}) {
  const refresh = $('btn-settings-refresh');
  if (refresh) refresh.disabled = true;
  setSettingsNotice('');
  try {
    const [settingsResult] = await Promise.allSettled([
      api('/api/settings'),
      loadSystemStatus(),
    ]);
    if (settingsResult.status === 'rejected') throw settingsResult.reason;
    renderSettingsSnapshot(settingsResult.value || {});
    await Promise.allSettled([
      loadSettingsSectionData(state.settings.section, { quiet: true }),
      loadOpenBDXStatus({ quiet: true }),
    ]);
    if (!quiet) toast('settings refreshed');
  } catch (error) {
    setSettingsNotice(error.message || 'Unable to load Settings.', 'error');
    throw error;
  } finally {
    if (refresh) refresh.disabled = false;
  }
}

function closeWifiScanResults() {
  const panel = $('body-wifi-scan-results');
  if (panel) panel.hidden = true;
}

function chooseScannedWifi(network = {}) {
  if (network.wpa3_only) {
    toast('WPA3-only networks are not supported. Enable WPA2 or transition mode.', 7200);
    return;
  }
  const input = $('body-wifi-ssid');
  if (input) {
    input.value = String(network.ssid || '');
    input.focus();
  }
  closeWifiScanResults();
  if (network.transition) {
    toast('This WPA2/WPA3 network will be joined using WPA2 only.', 6200);
  }
}

function renderWifiScanResults(networks) {
  const panel = $('body-wifi-scan-results');
  const list = $('body-wifi-scan-list');
  if (!panel || !list) return;

  if (!networks.length) {
    list.innerHTML = '<div class="wifi-profile-empty muted">No Wi-Fi networks were found.</div>';
  } else {
    list.innerHTML = networks.map((network, index) => {
      const ssid = String(network.ssid || '');
      const signal = Number(network.signal || 0);
      const security = network.security ? String(network.security) : 'Open';
      const wpa3Only = Boolean(network.wpa3_only);
      const transition = Boolean(network.transition);
      const policy = wpa3Only ? 'WPA3 only · unsupported' : (transition ? 'will use WPA2' : '');
      const meta = [ `${signal}%`, security, policy ].filter(Boolean).join(' · ');
      return `
        <button type="button" class="wifi-scan-row" data-network-index="${index}" data-security-mode="${escapeHtml(network.security_mode || '')}" ${wpa3Only ? 'disabled aria-disabled="true" title="WPA3-only networks are not supported"' : ''}>
          <span class="wifi-scan-name">${escapeHtml(ssid || '(hidden network)')}</span>
          <span class="wifi-scan-meta">${escapeHtml(meta)}</span>
        </button>`;
    }).join('');
    list.querySelectorAll('.wifi-scan-row').forEach((row) => {
      row.addEventListener('click', () => {
        const index = Number(row.dataset.networkIndex);
        const network = Number.isInteger(index) ? networks[index] : null;
        if (network) chooseScannedWifi(network);
      });
    });
  }
  panel.hidden = false;
}

async function scanSettingsWifi() {
  const button = $('btn-settings-scan');
  if (button) {
    button.disabled = true;
    button.textContent = 'Scanning…';
  }
  try {
    const response = await api('/api/settings/wifi-scan', { method: 'POST', body: '{}' });
    state.settings.networks = Array.isArray(response.networks) ? response.networks : [];
    renderWifiScanResults(state.settings.networks);
    toast(`${state.settings.networks.length} Wi-Fi network${state.settings.networks.length === 1 ? '' : 's'} found`);
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = 'Scan';
    }
  }
}

async function saveDuckIdentity() {
  const button = $('duck-identity-form')?.querySelector('button[type="submit"]');
  if (button) button.disabled = true;
  try {
    const duckName = $('duck-name')?.value || '';
    const response = await api('/api/settings/identity', {
      method: 'POST',
      body: JSON.stringify({ duck_name: duckName }),
    });
    const saved = response.settings || { duck_name: duckName };
    if (!state.settings.data) state.settings.data = {};
    state.settings.data.settings = saved;
    if (response.hostnames) {
      state.settings.data.hostnames = response.hostnames;
      renderDuckHostnames(response.hostnames);
    }
    document.title = saved.duck_name ? `${saved.duck_name} · PuddleDuck` : 'PuddleDuck';
    toast(response.hostnames?.external_hostname
      ? `duck name saved · ${response.hostnames.external_hostname}`
      : 'duck name saved');
  } finally {
    if (button) button.disabled = false;
  }
}

function downloadHttpsCaCertificate() {
  window.location.assign('/puddleduck-ca.crt');
}

async function saveBodyWifi() {
  const button = $('btn-save-body-wifi');
  if (button) button.disabled = true;
  try {
    const payload = {
      ssid: $('body-wifi-ssid')?.value || '',
      password: $('body-wifi-password')?.value || '',
      priority: Number($('body-wifi-priority')?.value || 50),
      open: Boolean($('body-wifi-open')?.checked),
      hidden: Boolean($('body-wifi-hidden')?.checked),
    };
    const response = await api('/api/settings/body-wifi', {
      method: 'POST',
      body: JSON.stringify(payload),
    });
    renderSettingsJob(response.job || {});
    resetBodyWifiForm();
    toast('body Wi-Fi update started');
  } finally {
    if (button) button.disabled = false;
  }
}

async function deleteBodyWifiProfile(ssid) {
  if (!ssid) return;
  if (!confirm(`Delete the saved Wi-Fi network “${ssid}”?`)) return;
  const response = await api(`/api/settings/body-wifi?ssid=${encodeURIComponent(ssid)}`, { method: 'DELETE' });
  renderSettingsJob(response.job || {});
  if (state.settings.editingSsid === ssid) resetBodyWifiForm();
  toast(`removing ${ssid}`);
}

async function saveHeadAccessPoint() {
  if (!confirm('Applying the head access point will disconnect clients currently joined to it. Continue?')) return;
  const button = $('btn-save-head-ap');
  if (button) button.disabled = true;
  try {
    const response = await api('/api/settings/head-ap', {
      method: 'POST',
      body: JSON.stringify({
        name: $('head-ap-name')?.value || '',
        password: $('head-ap-password')?.value || '',
      }),
    });
    renderSettingsJob(response.job || {});
    toast('head access-point update started');
  } finally {
    if (button) button.disabled = false;
  }
}



