async function saveDuckDriveSettings() {
  const editor = $('duck-drive-yaml-editor');
  const button = $('btn-duck-drive-save');
  if (!editor) return;
  if (button) button.disabled = true;
  setEditorStatus('duck-drive-editor-status', 'Validating and saving…');
  try {
    const response = await api('/api/settings/duck-drive', {
      method: 'PUT',
      body: JSON.stringify({ yaml: editor.value }),
    });
    renderDuckDriveSettings(response);
    toast(response.message || 'Duck Drive settings saved');
  } catch (error) {
    setEditorStatus('duck-drive-editor-status', error.message || 'Unable to save duck_control.yaml.', 'error');
    throw error;
  } finally {
    if (button) button.disabled = false;
  }
}

async function deleteDuckDriveSettings() {
  if (!confirm('Delete duck_control.yaml and return to the built-in defaults?')) return;
  const response = await api('/api/settings/duck-drive', { method: 'DELETE' });
  renderDuckDriveSettings(response);
  toast(response.message || 'Duck Drive defaults restored');
}

function bluetoothStatusLabels(device = {}) {
  const labels = [];
  if (device.connected) labels.push('connected');
  if (device.paired) labels.push('paired');
  if (device.trusted) labels.push('trusted');
  if (device.blocked) labels.push('blocked');
  return labels.length ? labels.join(' · ') : 'not paired';
}

function bluetoothActionButton(label, action, device, className = '') {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = label;
  if (className) button.className = className;
  button.disabled = state.settings.bluetooth.loading || state.settings.bluetooth.scanning;
  button.addEventListener('click', () => runBluetoothAction(action, device.address).catch((error) => toast(error.message, 6000)));
  return button;
}

function renderBluetoothControllerTemplate() {
  const template = state.settings.bluetooth.controllerTemplate;
  const panel = $('bluetooth-controller-template');
  const text = $('bluetooth-controller-template-text');
  const button = $('btn-edit-bluetooth-controller');
  if (!panel || !text || !button) return;
  if (!template) {
    panel.hidden = true;
    return;
  }
  const filename = String(template.filename || template.name || '');
  const device = String(template.device || 'controller');
  if (template.ok === false) {
    text.textContent = template.message || 'Controller mapping template could not be created.';
    panel.dataset.tone = 'error';
    button.hidden = true;
  } else {
    text.textContent = template.created
      ? `Created ${filename} for ${device}. Add its button and axis mappings before using the controller.`
      : `${device} already uses ${filename}.`;
    panel.dataset.tone = template.created ? 'warn' : '';
    button.hidden = !filename;
  }
  panel.hidden = false;
}

async function editBluetoothControllerTemplate() {
  const template = state.settings.bluetooth.controllerTemplate;
  const filename = String(template?.filename || template?.name || '');
  if (!filename) throw new Error('No generated controller mapping is available.');
  if (editorModified('controller-yaml-editor', state.settings.controllers.original)
      && state.settings.controllers.selectedName
      && !confirm('Discard unsaved controller changes?')) return;
  setSettingsSection('controllers', { load: false });
  await loadControllersSettings({ quiet: true, select: false, force: true, skipDirtyCheck: true });
  await loadControllerFile(filename, { quiet: true, skipDirtyCheck: true });
  $('controller-yaml-editor')?.focus();
}

function headBluetoothSpeakerDeviceButton(label, action, device, className = '') {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = label;
  if (className) button.className = className;
  button.disabled = state.settings.bluetooth.speakerBusy;
  button.addEventListener('click', () => runHeadBluetoothSpeakerDeviceAction(action, device.address)
    .catch((error) => toast(error.message, 7000)));
  return button;
}

function renderHeadBluetoothSpeaker(speaker = {}) {
  const available = Boolean(speaker.available);
  const enabled = Boolean(speaker.enabled);
  const active = Boolean(speaker.active);
  const pulseReady = Boolean(speaker.pulse?.ready);
  const phase = String(speaker.phase || speaker.runtime?.phase || '').toLowerCase();
  const starting = Boolean(speaker.starting) || phase === 'starting' || phase === 'preparing';
  const failed = phase === 'failed';
  let tone = 'error';
  let label = 'unavailable';
  if (available && !enabled) { tone = ''; label = 'disabled'; }
  if (available && enabled && !failed && (starting || !active || !pulseReady)) {
    tone = 'running';
    label = 'starting';
  }
  if (available && enabled && active && pulseReady && !failed) { tone = 'ok'; label = 'enabled'; }
  setSettingsStatusChip('head-bluetooth-speaker-status-chip', label, tone);

  setText('head-bluetooth-speaker-name', speaker.name || '–');
  const adapter = speaker.adapter || {};
  const adapterPresent = Boolean(adapter.address || adapter.hci || Number.isInteger(adapter.index));
  const adapterIdentity = adapterPresent
    ? `${adapter.hci || 'Bluetooth'}${adapter.address ? ` · ${adapter.address}` : ''}`
    : '';
  setText('head-bluetooth-speaker-adapter', adapterIdentity
    || (starting ? 'Detecting adapter…' : (available ? 'No adapter detected' : 'Unavailable')));
  const radioLabel = adapter.external_usb
    ? `external USB${adapter.product ? ` · ${adapter.product}` : ''}`
    : (adapter.shared_wifi_radio ? 'shared Wi-Fi/Bluetooth radio' : (adapter.kind || adapter.bus || 'Bluetooth'));
  setText('head-bluetooth-speaker-radio', adapterPresent ? radioLabel : '–');
  const headAp = speaker.head_ap || {};
  let headApLabel = headAp.active ? 'enabled' : 'off';
  if (headAp.radio_enabled === false || headAp.radio_disabled) {
    headApLabel = 'Wi-Fi radio off for Bluetooth';
  } else if (headAp.suspended) {
    headApLabel = 'access point paused for Bluetooth';
  }
  if (adapter.external_usb && headAp.active) headApLabel = 'enabled · separate radio';
  setText('head-bluetooth-speaker-ap', headApLabel);
  setText('head-bluetooth-speaker-mode', enabled
    ? (active && pulseReady ? 'discoverable · pairable · A2DP sink' : (starting ? 'starting' : 'enabled, waiting for service'))
    : 'off');
  const devices = Array.isArray(speaker.devices) ? speaker.devices : [];
  const connected = devices.filter((device) => device.connected);
  setText('head-bluetooth-speaker-connected', connected.length
    ? connected.map((device) => device.name || device.address).join(', ')
    : 'none');

  const toggle = $('btn-head-bluetooth-speaker-toggle');
  if (toggle) {
    toggle.textContent = state.settings.bluetooth.speakerBusy
      ? (enabled ? 'Disabling…' : 'Enabling…')
      : (enabled ? 'Disable speaker' : 'Enable speaker');
    // An enabled optional service must always remain disable-able, even if a
    // transient status/inventory problem makes it report unavailable.
    toggle.disabled = state.settings.bluetooth.speakerBusy || (!enabled && !available);
    toggle.classList.toggle('danger', enabled);
  }

  const message = $('head-bluetooth-speaker-message');
  if (message) {
    message.textContent = speaker.message || '';
    message.dataset.tone = starting ? '' : (available && (!enabled || (active && pulseReady)) ? '' : 'error');
    message.hidden = !speaker.message;
  }

  const list = $('head-bluetooth-speaker-devices');
  if (!list) return;
  list.replaceChildren();
  if (!devices.length) return;
  const heading = document.createElement('h4');
  heading.className = 'bluetooth-group-title';
  heading.textContent = 'Paired sources';
  list.appendChild(heading);
  for (const device of devices) {
    const row = document.createElement('div');
    row.className = 'bluetooth-device-row';
    row.dataset.connected = device.connected ? 'true' : 'false';
    const main = document.createElement('div');
    main.className = 'bluetooth-device-main';
    const name = document.createElement('div');
    name.className = 'bluetooth-device-name';
    const strong = document.createElement('strong');
    strong.textContent = String(device.name || device.address || 'Bluetooth source');
    name.appendChild(strong);
    if (device.connected) {
      const chip = document.createElement('span');
      chip.className = 'settings-status-chip';
      chip.dataset.tone = 'ok';
      chip.textContent = 'connected';
      name.appendChild(chip);
    }
    const meta = document.createElement('div');
    meta.className = 'bluetooth-device-meta';
    meta.textContent = `${device.address || ''} · ${bluetoothStatusLabels(device)}`;
    main.append(name, meta);
    const actions = document.createElement('div');
    actions.className = 'bluetooth-device-actions';
    if (device.connected) actions.appendChild(headBluetoothSpeakerDeviceButton('Disconnect', 'disconnect', device));
    actions.appendChild(headBluetoothSpeakerDeviceButton('Forget', 'remove', device, 'danger'));
    row.append(main, actions);
    list.appendChild(row);
  }
}

async function toggleHeadBluetoothSpeaker() {
  if (state.settings.bluetooth.speakerBusy) return;
  const speaker = state.settings.bluetooth.data?.head_speaker || {};
  const enabled = !Boolean(speaker.enabled);
  if (enabled) {
    const adapter = speaker.adapter || {};
    if (adapter.shared_wifi_radio && !adapter.external_usb && !window.confirm(
      'Enable the head Bluetooth speaker? The integrated Bluetooth radio shares hardware with the head Wi-Fi access point, so head Wi-Fi will be turned off until speaker mode is disabled.'
    )) return;
  }
  state.settings.bluetooth.speakerBusy = true;
  renderHeadBluetoothSpeaker(speaker);
  try {
    const response = await api('/api/settings/bluetooth/speaker', {
      method: 'POST',
      body: JSON.stringify({ enabled }),
    });
    renderBluetoothSettings(response);
    toast(response.head_speaker?.message || `Head Bluetooth speaker ${enabled ? 'enabled' : 'disabled'}`, 6200);
  } finally {
    state.settings.bluetooth.speakerBusy = false;
    renderHeadBluetoothSpeaker(state.settings.bluetooth.data?.head_speaker || {});
  }
}

async function runHeadBluetoothSpeakerDeviceAction(action, address) {
  if (state.settings.bluetooth.speakerBusy) return;
  if (action === 'remove' && !window.confirm(`Forget Bluetooth device ${address}?`)) return;
  state.settings.bluetooth.speakerBusy = true;
  renderHeadBluetoothSpeaker(state.settings.bluetooth.data?.head_speaker || {});
  try {
    const response = await api('/api/settings/bluetooth/speaker/device', {
      method: 'POST',
      body: JSON.stringify({ action, address }),
    });
    renderBluetoothSettings(response);
    toast(response.head_speaker?.message || `Bluetooth device ${action} complete`, 5200);
  } finally {
    state.settings.bluetooth.speakerBusy = false;
    renderHeadBluetoothSpeaker(state.settings.bluetooth.data?.head_speaker || {});
  }
}

function renderBluetoothSettings(response = {}) {
  const previousSpeaker = state.settings.bluetooth.data?.head_speaker || {};
  const headSpeaker = response.head_speaker || previousSpeaker;
  response.head_speaker = headSpeaker;
  state.settings.bluetooth.data = response;
  renderHeadBluetoothSpeaker(headSpeaker);
  if (Object.prototype.hasOwnProperty.call(response, 'controller_template')) {
    state.settings.bluetooth.controllerTemplate = response.controller_template || null;
  }
  renderBluetoothControllerTemplate();
  const available = Boolean(response.available);
  setSettingsStatusChip('bluetooth-status-chip', available ? 'available' : 'unavailable', available ? 'ok' : 'error');
  const controller = response.controller || {};
  const controllerText = available
    ? `${controller.name || 'Bluetooth'}${controller.address ? ` · ${controller.address}` : ''} · ${controller.powered ? 'powered' : 'off'}`
    : (response.message || 'bluetoothctl is not installed');
  setText('bluetooth-controller-status', controllerText);
  const message = $('bluetooth-message');
  if (message) {
    message.textContent = response.message || '';
    message.dataset.tone = available ? '' : 'error';
    message.hidden = !response.message;
  }
  const list = $('bluetooth-device-list');
  if (!list) return;
  list.replaceChildren();
  if (!available) {
    const empty = document.createElement('div');
    empty.className = 'wifi-profile-empty muted';
    empty.textContent = response.message || 'Bluetooth is unavailable.';
    list.appendChild(empty);
    return;
  }
  const devices = Array.isArray(response.devices) ? response.devices : [];
  if (!devices.length) {
    const empty = document.createElement('div');
    empty.className = 'wifi-profile-empty muted';
    empty.textContent = 'No Bluetooth devices are known. Scan to discover controllers and audio devices.';
    list.appendChild(empty);
    return;
  }
  const groups = [
    ['controller', 'Controllers'],
    ['audio', 'Audio'],
    ['other', 'Other devices'],
  ];
  for (const [kind, title] of groups) {
    const groupDevices = devices.filter((device) => String(device.kind || 'other') === kind);
    if (!groupDevices.length) continue;
    const group = document.createElement('section');
    group.className = 'bluetooth-group';
    const heading = document.createElement('h4');
    heading.className = 'bluetooth-group-title';
    heading.textContent = title;
    group.appendChild(heading);
    for (const device of groupDevices) {
      const row = document.createElement('div');
      row.className = 'bluetooth-device-row';
      row.dataset.connected = device.connected ? 'true' : 'false';
      const main = document.createElement('div');
      main.className = 'bluetooth-device-main';
      const name = document.createElement('div');
      name.className = 'bluetooth-device-name';
      const strong = document.createElement('strong');
      strong.textContent = String(device.name || device.address || 'Bluetooth device');
      name.appendChild(strong);
      if (device.connected) {
        const chip = document.createElement('span');
        chip.className = 'settings-status-chip';
        chip.dataset.tone = 'ok';
        chip.textContent = 'connected';
        name.appendChild(chip);
      }
      const meta = document.createElement('div');
      meta.className = 'bluetooth-device-meta';
      meta.textContent = `${device.address || ''} · ${bluetoothStatusLabels(device)}${device.rssi ? ` · RSSI ${device.rssi}` : ''}`;
      main.append(name, meta);
      const actions = document.createElement('div');
      actions.className = 'bluetooth-device-actions';
      if (!device.paired) {
        actions.appendChild(bluetoothActionButton('Pair', 'pair', device));
      } else {
        actions.appendChild(bluetoothActionButton(device.connected ? 'Disconnect' : 'Connect', device.connected ? 'disconnect' : 'connect', device));
        actions.appendChild(bluetoothActionButton('Unpair', 'remove', device, 'danger'));
      }
      row.append(main, actions);
      group.appendChild(row);
    }
    list.appendChild(group);
  }
}

async function loadBluetoothSettings({ quiet = false } = {}) {
  if (state.settings.bluetooth.loading) return;
  state.settings.bluetooth.loading = true;
  setSettingsStatusChip('bluetooth-status-chip', 'loading', 'running');
  try {
    const response = await api('/api/settings/bluetooth');
    renderBluetoothSettings(response);
    if (!quiet) toast('Bluetooth devices refreshed');
    return response;
  } catch (error) {
    setSettingsStatusChip('bluetooth-status-chip', 'error', 'error');
    renderHeadBluetoothSpeaker({ available: false, enabled: false, active: false, message: error.message || 'Unable to query head Bluetooth speaker.' });
    const message = $('bluetooth-message');
    if (message) {
      message.textContent = error.message || 'Unable to query Bluetooth.';
      message.dataset.tone = 'error';
      message.hidden = false;
    }
    throw error;
  } finally {
    state.settings.bluetooth.loading = false;
    if (state.settings.bluetooth.data) renderBluetoothSettings(state.settings.bluetooth.data);
  }
}

async function scanBluetoothSettings() {
  if (state.settings.bluetooth.scanning) return;
  state.settings.bluetooth.scanning = true;
  const button = $('btn-bluetooth-scan');
  if (button) { button.disabled = true; button.textContent = 'Scanning…'; }
  setSettingsStatusChip('bluetooth-status-chip', 'scanning', 'running');
  try {
    const response = await api('/api/settings/bluetooth/scan', {
      method: 'POST',
      body: JSON.stringify({ seconds: 8 }),
    });
    renderBluetoothSettings(response);
    toast(response.message || 'Bluetooth scan complete');
  } finally {
    state.settings.bluetooth.scanning = false;
    if (button) { button.disabled = false; button.textContent = 'Scan for devices'; }
    if (state.settings.bluetooth.data) renderBluetoothSettings(state.settings.bluetooth.data);
  }
}

async function runBluetoothAction(action, address) {
  state.settings.bluetooth.loading = true;
  renderBluetoothSettings(state.settings.bluetooth.data || {});
  try {
    const response = await api('/api/settings/bluetooth/action', {
      method: 'POST',
      body: JSON.stringify({ action, address }),
    });
    renderBluetoothSettings(response);
    if (response.controller_template?.created) {
      state.settings.controllers.items = [];
      state.settings.controllers.current = null;
      state.settings.controllers.selectedName = '';
      state.settings.controllers.original = '';
    }
    toast(response.message || `Bluetooth ${action} requested`, response.controller_template ? 6200 : 4200);
  } finally {
    state.settings.bluetooth.loading = false;
    if (state.settings.bluetooth.data) renderBluetoothSettings(state.settings.bluetooth.data);
  }
}

function controllerSourceText(item = {}) {
  if (item.source === 'built-in') return item.override ? 'user override' : 'built-in';
  if (item.source === 'user') return item.override ? 'user override' : 'user';
  return item.source || 'new';
}

function renderControllerList(items = state.settings.controllers.items) {
  state.settings.controllers.items = Array.isArray(items) ? items : [];
  const list = $('controller-file-list');
  if (!list) return;
  list.replaceChildren();
  if (!state.settings.controllers.items.length) {
    const empty = document.createElement('div');
    empty.className = 'muted';
    empty.textContent = 'No controller definitions were found.';
    list.appendChild(empty);
    return;
  }
  for (const item of state.settings.controllers.items) {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'controller-file-row';
    row.classList.toggle('selected', item.name === state.settings.controllers.selectedName);
    row.dataset.error = item.error ? 'true' : 'false';
    const name = document.createElement('strong');
    name.textContent = item.name;
    const meta = document.createElement('small');
    const controllers = Array.isArray(item.controllers) ? item.controllers.length : 0;
    meta.textContent = item.error || `${controllerSourceText(item)} · ${controllers} definition${controllers === 1 ? '' : 's'}`;
    row.append(name, meta);
    row.addEventListener('click', () => loadControllerFile(item.name).catch((error) => toast(error.message, 5200)));
    list.appendChild(row);
  }
}

function renderControllerEditor(response = {}) {
  state.settings.controllers.current = response;
  state.settings.controllers.selectedName = String(response.name || '');
  state.settings.controllers.original = String(response.yaml || '');
  state.settings.controllers.isNew = response.source === 'new';
  const name = $('controller-file-name');
  const editor = $('controller-yaml-editor');
  if (name) {
    name.value = response.name || '';
    name.readOnly = !state.settings.controllers.isNew;
  }
  if (editor) {
    editor.disabled = false;
    editor.value = state.settings.controllers.original;
  }
  const source = controllerSourceText(response);
  setSettingsStatusChip('controller-source-chip', source, response.source === 'user' ? 'ok' : response.source === 'built-in' ? 'running' : 'warn');
  const summaries = Array.isArray(response.controllers) ? response.controllers : [];
  const summary = summaries.map((item) => {
    const kyberpad = item.kyberpad ? ' · KyberPad' : '';
    return `${item.name || item.device} (${item.axes || 0} axes, ${item.buttons || 0} buttons${kyberpad})`;
  }).join('; ');
  setText('controller-file-details', `${response.path || response.write_path || ''}${summary ? ` · ${summary}` : ''}`);
  setEditorStatus('controller-editor-status', response.template ? 'New-file template' : `${formatBytes(response.bytes)} · ${formatPolicyDate(response.modified)}`);
  const save = $('btn-controller-save');
  if (save) {
    save.disabled = false;
    save.textContent = response.source === 'built-in' ? 'Save override' : 'Save';
  }
  const reload = $('btn-controller-reload');
  if (reload) reload.disabled = false;
  const interactive = $('btn-controller-interactive');
  if (interactive) interactive.disabled = summaries.length === 0;
  const del = $('btn-controller-delete');
  if (del) {
    del.disabled = response.source !== 'user';
    del.textContent = response.override ? 'Delete override' : 'Delete file';
  }
  state.settings.controllers.kyberpadExport = null;
  updateControllerKyberpadExportButton();
  renderControllerList();
}


function setInteractiveControllerStatus(message, tone = '') {
  const element = $('controller-interactive-status');
  if (!element) return;
  element.hidden = false;
  element.textContent = String(message || '');
  element.dataset.tone = tone;
}

function resetInteractiveControllerDetection() {
  state.settings.controllers.interactive.selected = null;
  setText('controller-interactive-detected', 'Press a button or move an axis');
  setText('controller-interactive-value', 'For diagonal movement, the axis with the greatest displacement is selected.');
  const input = $('controller-interactive-action');
  if (input) {
    input.value = '';
    input.disabled = true;
  }
  const save = $('btn-controller-interactive-save');
  if (save) save.disabled = true;
}

function renderInteractiveControllerEvent(event) {
  if (!event || !['button', 'axis'].includes(event.kind)) return;
  state.settings.controllers.interactive.selected = event;
  const title = event.kind === 'button' ? `Button ${event.code}` : `Axis ${event.code}`;
  setText('controller-interactive-detected', title);
  if (event.kind === 'axis') {
    const strength = Math.round(Math.max(0, Math.min(1, Number(event.strength) || 0)) * 100);
    setText('controller-interactive-value', `${strength}% movement · raw value ${event.value}`);
  } else {
    setText('controller-interactive-value', `Raw button index ${event.code}`);
  }
  const input = $('controller-interactive-action');
  if (input) {
    input.disabled = false;
    input.value = String(event.action || '');
    input.focus();
    input.select();
  }
  const save = $('btn-controller-interactive-save');
  if (save) save.disabled = false;
}

function scheduleInteractiveControllerPoll(delay = 100) {
  const interactive = state.settings.controllers.interactive;
  clearTimeout(interactive.timer);
  interactive.timer = setTimeout(pollInteractiveController, delay);
}

async function pollInteractiveController() {
  const interactive = state.settings.controllers.interactive;
  const dialog = $('controller-interactive-dialog');
  if (!interactive.session || !dialog?.open) return;
  const session = interactive.session;
  try {
    const response = await api(`/api/settings/controllers/interactive/event?session=${encodeURIComponent(session)}&after=${encodeURIComponent(interactive.lastSeq)}`);
    if (interactive.session !== session) return;
    interactive.lastSeq = Number(response.last_seq) || interactive.lastSeq;
    for (const event of Array.isArray(response.events) ? response.events : []) {
      renderInteractiveControllerEvent(event);
    }
    scheduleInteractiveControllerPoll(100);
  } catch (error) {
    if (interactive.session !== session) return;
    interactive.connected = false;
    interactive.session = '';
    setInteractiveControllerStatus(error.message || 'Controller disconnected.', 'error');
    setText('controller-interactive-device', 'disconnected');
    const input = $('controller-interactive-action');
    if (input) input.disabled = true;
    const save = $('btn-controller-interactive-save');
    if (save) save.disabled = true;
  }
}

async function stopInteractiveControllerSession() {
  const interactive = state.settings.controllers.interactive;
  clearTimeout(interactive.timer);
  interactive.timer = 0;
  const session = interactive.session;
  interactive.session = '';
  interactive.connected = false;
  interactive.lastSeq = 0;
  interactive.selected = null;
  if (!session) return;
  try {
    await api('/api/settings/controllers/interactive/stop', {
      method: 'POST',
      body: JSON.stringify({ session }),
    });
  } catch {
    // The server expires abandoned sessions automatically.
  }
}

function closeInteractiveControllerDialog() {
  const dialog = $('controller-interactive-dialog');
  if (dialog?.open) dialog.close();
  else stopInteractiveControllerSession();
}

async function connectInteractiveController() {
  const current = state.settings.controllers.current || {};
  const name = String($('controller-file-name')?.value || current.name || '').trim();
  const yaml = String($('controller-yaml-editor')?.value || '');
  const interactive = state.settings.controllers.interactive;
  const connectToken = ++interactive.connectToken;
  const select = $('controller-interactive-controller');
  const controllerIndex = Number(select?.value ?? interactive.controllerIndex) || 0;
  interactive.controllerIndex = controllerIndex;
  clearTimeout(interactive.timer);
  interactive.timer = 0;
  interactive.session = '';
  interactive.connected = false;
  interactive.lastSeq = 0;
  resetInteractiveControllerDetection();
  setInteractiveControllerStatus('Connecting to the selected controller…');
  setText('controller-interactive-device', 'connecting…');

  const response = await api('/api/settings/controllers/interactive/start', {
    method: 'POST',
    body: JSON.stringify({ name, yaml, controller_index: controllerIndex }),
  });
  if (interactive.connectToken !== connectToken) {
    api('/api/settings/controllers/interactive/stop', {
      method: 'POST',
      body: JSON.stringify({ session: response.session || '' }),
    }).catch(() => {});
    return null;
  }
  interactive.session = String(response.session || '');
  interactive.connected = true;
  interactive.lastSeq = 0;
  setInteractiveControllerStatus(response.message || `Connected to ${response.device}.`, 'ok');
  setText('controller-interactive-device', `${response.device || 'controller'} · ${response.path || ''} · ${response.input_kind || 'input'}`);
  scheduleInteractiveControllerPoll(0);
  return response;
}

function controllerUnavailableNotice(error) {
  const message = String(error?.message || '');
  const match = message.match(/controller\s+(.+?)\s+is not connected(?:\.|$)/i);
  return match ? `Controller ${match[1]} is not connected.` : '';
}

function showInteractiveControllerConnectNotice(message) {
  const notice = $('controller-interactive-connect-notice');
  setText('controller-interactive-connect-message', message);
  if (!notice || notice.open) return;
  if (typeof notice.show === 'function') notice.show();
  else notice.setAttribute('open', '');
}

function hideInteractiveControllerConnectNotice({ cancelRetry = false } = {}) {
  const interactive = state.settings.controllers.interactive;
  clearTimeout(interactive.retryTimer);
  clearTimeout(interactive.retryStopTimer);
  interactive.retryTimer = 0;
  interactive.retryStopTimer = 0;
  interactive.retryDeadline = 0;
  interactive.retryActive = false;
  if (cancelRetry) interactive.connectToken += 1;
  const notice = $('controller-interactive-connect-notice');
  if (notice?.open) notice.close();
  else notice?.removeAttribute('open');
}

function showInteractiveControllerEditor() {
  const dialog = $('controller-interactive-dialog');
  if (!dialog || dialog.open) return;
  if (typeof dialog.showModal === 'function') dialog.showModal();
  else dialog.setAttribute('open', '');
}

async function connectInteractiveControllerWithRetry() {
  const interactive = state.settings.controllers.interactive;
  hideInteractiveControllerConnectNotice({ cancelRetry: true });
  interactive.retryActive = true;
  interactive.retryDeadline = Date.now() + 10000;
  interactive.retryStopTimer = setTimeout(() => {
    hideInteractiveControllerConnectNotice({ cancelRetry: true });
  }, 10000);

  const attempt = async (initial = false) => {
    if (!interactive.retryActive) return null;
    try {
      const response = await connectInteractiveController();
      if (!interactive.retryActive) return null;
      hideInteractiveControllerConnectNotice();
      showInteractiveControllerEditor();
      return response;
    } catch (error) {
      if (!interactive.retryActive) return null;
      const notice = controllerUnavailableNotice(error);
      if (!notice) {
        hideInteractiveControllerConnectNotice({ cancelRetry: true });
        if (initial) throw error;
        toast(error.message || 'Unable to connect to the controller.', 7200);
        return null;
      }
      showInteractiveControllerConnectNotice(notice);
      if (Date.now() >= interactive.retryDeadline) {
        hideInteractiveControllerConnectNotice({ cancelRetry: true });
        return null;
      }
      clearTimeout(interactive.retryTimer);
      interactive.retryTimer = setTimeout(() => {
        attempt(false).catch((retryError) => {
          hideInteractiveControllerConnectNotice({ cancelRetry: true });
          toast(retryError.message || 'Unable to connect to the controller.', 7200);
        });
      }, 750);
      return null;
    }
  };

  return attempt(true);
}

async function openInteractiveControllerDialog() {
  const current = state.settings.controllers.current || {};
  const summaries = Array.isArray(current.controllers) ? current.controllers : [];
  if (!summaries.length) throw new Error('the selected YAML does not contain a controller definition');
  const dialog = $('controller-interactive-dialog');
  const select = $('controller-interactive-controller');
  const label = $('controller-interactive-controller-label');
  if (!dialog || !select) throw new Error('interactive controller dialog is unavailable');

  select.replaceChildren();
  for (const item of summaries) {
    const option = document.createElement('option');
    option.value = String(item.index);
    option.textContent = item.name || item.device || `Controller ${Number(item.index) + 1}`;
    select.appendChild(option);
  }
  select.value = String(summaries[0].index ?? 0);
  if (label) label.hidden = summaries.length <= 1;
  state.settings.controllers.interactive.controllerIndex = Number(select.value) || 0;
  resetInteractiveControllerDetection();
  await connectInteractiveControllerWithRetry();
}

async function saveInteractiveControllerMapping() {
  const interactive = state.settings.controllers.interactive;
  const selected = interactive.selected;
  const input = $('controller-interactive-action');
  const action = String(input?.value || '').trim();
  if (!interactive.session || !interactive.connected) throw new Error('the controller is not connected');
  if (!selected) throw new Error('press a button or move an axis first');
  if (!action) throw new Error('action name may not be empty');

  const name = String($('controller-file-name')?.value || '').trim();
  const editor = $('controller-yaml-editor');
  if (!name || !editor) throw new Error('controller filename is required');
  const save = $('btn-controller-interactive-save');
  if (save) save.disabled = true;
  try {
    const response = await api('/api/settings/controllers/interactive/apply', {
      method: 'POST',
      body: JSON.stringify({
        session: interactive.session,
        name,
        yaml: editor.value,
        controller_index: interactive.controllerIndex,
        kind: selected.kind,
        code: selected.code,
        action,
      }),
    });
    await loadControllersSettings({ quiet: true, select: false, force: true, skipDirtyCheck: true });
    renderControllerEditor(response);
    interactive.selected = { ...selected, action };
    if (input) input.value = action;
    setInteractiveControllerStatus(`Saved ${selected.kind} ${selected.code} as ${action}. Restart the state service and any running policy to use the new mapping.`, 'ok');
    toast(`${selected.kind === 'button' ? 'Button' : 'Axis'} ${selected.code} → ${action}`, 4200);
  } finally {
    if (save) save.disabled = false;
  }
}

function controllerEditorHasKyberpad() {
  const editor = $('controller-yaml-editor');
  return Boolean(editor && !editor.disabled && /^\s*kyberpad\s*:/m.test(String(editor.value || '')));
}

function updateControllerKyberpadExportButton() {
  const button = $('btn-controller-export-kyberpad');
  if (!button) return;
  const available = controllerEditorHasKyberpad();
  button.hidden = !available;
  button.disabled = !available;
}

async function loadKyberpadExport(controllerIndex = 0) {
  const name = String($('controller-file-name')?.value || '').trim();
  const yaml = String($('controller-yaml-editor')?.value || '');
  if (!name) throw new Error('controller filename is required');
  if (!yaml.trim()) throw new Error('controller YAML is empty');

  setText('kyberpad-export-status', 'Validating controller YAML and generating INI…');
  const response = await api('/api/settings/controllers/kyberpad-export', {
    method: 'POST',
    body: JSON.stringify({ name, yaml, controller_index: Number(controllerIndex) || 0 }),
  });
  state.settings.controllers.kyberpadExport = response;

  const content = $('kyberpad-export-content');
  if (content) content.value = String(response.content || '');
  setText('kyberpad-export-description', `${response.controller || 'Controller'} · ${response.filename || 'kyberpad.ini'}`);
  setText('kyberpad-export-status', `${formatBytes(response.bytes)} · KyberPad Config v3.0`);

  const select = $('kyberpad-export-controller');
  const selectLabel = $('kyberpad-export-controller-label');
  const options = Array.isArray(response.kyberpads) ? response.kyberpads : [];
  if (select) {
    select.replaceChildren();
    for (const item of options) {
      const option = document.createElement('option');
      option.value = String(item.index);
      option.textContent = item.name || item.device || `Controller ${Number(item.index) + 1}`;
      option.selected = Number(item.index) === Number(response.controller_index);
      select.appendChild(option);
    }
  }
  if (selectLabel) selectLabel.hidden = options.length <= 1;
  const download = $('btn-kyberpad-export-download');
  const copy = $('btn-kyberpad-export-copy');
  if (download) download.disabled = !response.content;
  if (copy) copy.disabled = !response.content;
  return response;
}

async function openKyberpadExportDialog() {
  const dialog = $('kyberpad-export-dialog');
  if (!dialog) throw new Error('KyberPad export dialog is unavailable');
  const summaries = Array.isArray(state.settings.controllers.current?.controllers)
    ? state.settings.controllers.current.controllers
    : [];
  const first = summaries.find((item) => item.kyberpad)?.index ?? 0;
  state.settings.controllers.kyberpadExport = null;
  const content = $('kyberpad-export-content');
  if (content) content.value = '';
  const download = $('btn-kyberpad-export-download');
  const copy = $('btn-kyberpad-export-copy');
  if (download) download.disabled = true;
  if (copy) copy.disabled = true;
  setText('kyberpad-export-description', 'Export the selected controller\'s KyberPad layout as an INI file.');
  setText('kyberpad-export-status', 'Preparing export…');
  if (typeof dialog.showModal === 'function') dialog.showModal();
  else dialog.setAttribute('open', '');
  try {
    await loadKyberpadExport(first);
  } catch (error) {
    setText('kyberpad-export-status', error.message || 'Unable to export KyberPad configuration.');
    throw error;
  }
}

function downloadKyberpadExport() {
  const response = state.settings.controllers.kyberpadExport || {};
  const content = String(response.content || '');
  if (!content) return;
  const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = String(response.filename || 'kyberpad.ini');
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

async function copyKyberpadExport() {
  const content = String(state.settings.controllers.kyberpadExport?.content || '');
  if (!content) return;
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(content);
  } else {
    const textarea = $('kyberpad-export-content');
    if (!textarea) throw new Error('clipboard is unavailable');
    textarea.focus();
    textarea.select();
    if (!document.execCommand('copy')) throw new Error('clipboard copy failed');
    textarea.setSelectionRange(0, 0);
  }
  toast('KyberPad INI copied', 3200);
}

async function loadControllersSettings({ quiet = false, select = true, force = false, skipDirtyCheck = false } = {}) {
  if (state.settings.controllers.loading) return;
  if (!force && (state.settings.controllers.items.length || state.settings.controllers.current)) {
    renderControllerList();
    return { ok: true, controllers: state.settings.controllers.items };
  }
  if (!skipDirtyCheck && force
      && editorModified('controller-yaml-editor', state.settings.controllers.original)
      && state.settings.controllers.selectedName
      && !confirm('Discard unsaved controller changes?')) return null;
  state.settings.controllers.loading = true;
  try {
    const response = await api('/api/settings/controllers');
    state.settings.controllers.items = Array.isArray(response.controllers) ? response.controllers : [];
    setText('controllers-directory', response.directory || '$HOME/controllers');
    renderControllerList();
    if (select) {
      const selectedExists = state.settings.controllers.items.some((item) => item.name === state.settings.controllers.selectedName);
      const name = selectedExists ? state.settings.controllers.selectedName : state.settings.controllers.items[0]?.name;
      if (name) await loadControllerFile(name, { quiet: true, skipDirtyCheck: force });
      else await startNewControllerFile({ skipDirtyCheck: force });
    }
    if (!quiet) toast('controller definitions refreshed');
    return response;
  } finally {
    state.settings.controllers.loading = false;
  }
}

async function loadControllerFile(name, { quiet = false, skipDirtyCheck = false } = {}) {
  const safeName = String(name || '').trim();
  if (!safeName) return;
  if (!skipDirtyCheck && editorModified('controller-yaml-editor', state.settings.controllers.original)
      && state.settings.controllers.selectedName
      && !confirm('Discard unsaved controller changes?')) return;
  const response = await api(`/api/settings/controllers/${encodeURIComponent(safeName)}`);
  renderControllerEditor(response);
  if (!quiet) toast(`${safeName} loaded`);
  return response;
}

function nextControllerFilename() {
  const names = new Set(state.settings.controllers.items.map((item) => item.name));
  let index = 1;
  let name = 'custom-controller.yaml';
  while (names.has(name)) {
    index += 1;
    name = `custom-controller-${index}.yaml`;
  }
  return name;
}

async function startNewControllerFile({ skipDirtyCheck = false } = {}) {
  if (!skipDirtyCheck && editorModified('controller-yaml-editor', state.settings.controllers.original)
      && state.settings.controllers.selectedName
      && !confirm('Discard unsaved controller changes?')) return;
  const name = nextControllerFilename();
  const response = await api(`/api/settings/controllers/${encodeURIComponent(name)}`);
  renderControllerEditor(response);
  $('controller-file-name')?.focus();
}

async function saveControllerFile() {
  const name = String($('controller-file-name')?.value || '').trim();
  const editor = $('controller-yaml-editor');
  const button = $('btn-controller-save');
  if (!name || !editor) throw new Error('controller filename is required');
  if (button) button.disabled = true;
  setEditorStatus('controller-editor-status', 'Validating and saving…');
  try {
    const response = await api(`/api/settings/controllers/${encodeURIComponent(name)}`, {
      method: 'PUT',
      body: JSON.stringify({ yaml: editor.value }),
    });
    await loadControllersSettings({ quiet: true, select: false, force: true, skipDirtyCheck: true });
    renderControllerEditor(response);
    toast(response.message || `${name} saved`, 5200);
  } catch (error) {
    setEditorStatus('controller-editor-status', error.message || 'Unable to save controller file.', 'error');
    throw error;
  } finally {
    if (button) button.disabled = false;
  }
}

async function deleteControllerFile() {
  const current = state.settings.controllers.current || {};
  const name = String(current.name || '');
  if (!name || current.source !== 'user') return;
  const verb = current.override ? 'remove the user override for' : 'delete';
  if (!confirm(`Really ${verb} ${name}?`)) return;
  const response = await api(`/api/settings/controllers/${encodeURIComponent(name)}`, { method: 'DELETE' });
  toast(response.message || `${name} deleted`, 5200);

  // The DELETE response is the effective built-in definition when an override
  // is removed. Keep that same file selected instead of jumping to the first
  // controller in the list.
  state.settings.controllers.original = String($('controller-yaml-editor')?.value || '');
  await loadControllersSettings({ quiet: true, select: false, force: true, skipDirtyCheck: true });
  if (response.source && response.yaml !== undefined) {
    renderControllerEditor(response);
    return;
  }

  state.settings.controllers.selectedName = '';
  state.settings.controllers.current = null;
  state.settings.controllers.original = '';
  const next = state.settings.controllers.items[0]?.name;
  if (next) await loadControllerFile(next, { quiet: true, skipDirtyCheck: true });
  else await startNewControllerFile({ skipDirtyCheck: true });
}
function formatUptime(seconds) {
  const value = Math.max(0, Math.floor(Number(seconds)));
  if (!Number.isFinite(value)) return '–';
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  if (days > 0) return `${days}d ${hours}h`;
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${minutes}m`;
}

const SYSTEM_ACTIONS = {
  reboot_body: {
    buttonId: 'btn-reboot-body',
    label: 'Reboot body',
    confirm: 'Confirm body reboot',
    path: '/api/system/reboot/body',
  },
  reboot_head: {
    buttonId: 'btn-reboot-head',
    label: 'Reboot head',
    confirm: 'Confirm head reboot',
    path: '/api/system/reboot/head',
  },
  recovery_body: {
    buttonId: 'btn-recovery-body',
    label: 'Reboot body to recovery',
    confirm: 'Confirm body recovery',
    path: '/api/system/recovery/body',
  },
  recovery_head: {
    buttonId: 'btn-recovery-head',
    label: 'Reboot head to recovery',
    confirm: 'Confirm head recovery',
    path: '/api/system/recovery/head',
  },
  shutdown: {
    buttonId: 'btn-shutdown-orins',
    label: 'Shutdown',
    confirm: 'Confirm shutdown',
    path: '/api/system/shutdown',
  },
};

function resetSystemActionArm({ preserveStatus = false } = {}) {
  if (state.system.armTimer) clearTimeout(state.system.armTimer);
  state.system.armTimer = 0;
  state.system.armedAction = '';
  state.system.armDeadlineMs = 0;
  for (const config of Object.values(SYSTEM_ACTIONS)) {
    const button = $(config.buttonId);
    if (!button) continue;
    button.textContent = config.label;
    button.classList.remove('power-confirm-armed');
  }
  if (!preserveStatus) renderSystemStatus();
}

function orinStateText(info, { reachable = true } = {}) {
  const pending = String(info?.pending_action || '');
  if (pending === 'recovery') return 'recovery mode pending';
  if (pending) return `${pending} pending`;
  if (!reachable) return 'offline';
  return 'ready';
}

function renderSystemStatus() {
  const info = state.system.info || {};
  const body = info.body || {};
  const head = info.head || {};
  const actions = info.actions || {};
  const policyActive = Boolean(info.policy_active || body.policy_active);
  const bodyPending = String(body.pending_action || '');
  const headPending = String(head.pending_action || '');
  const headReachable = Boolean(head.reachable);

  setText('orin-body-host', body.host || 'bdx-body');
  setText('orin-body-uptime', formatUptime(body.uptime_s));
  setText('orin-body-state', orinStateText(body));
  setText('orin-head-host', head.host || 'bdx-head');
  setText('orin-head-uptime', formatUptime(head.uptime_s));
  setText('orin-head-state', orinStateText(head, { reachable: headReachable }));

  const anyPending = Boolean(bodyPending || headPending);
  const commonDisabled = state.system.busy || policyActive;
  const rebootBody = $('btn-reboot-body');
  const rebootHead = $('btn-reboot-head');
  const recoveryBody = $('btn-recovery-body');
  const recoveryHead = $('btn-recovery-head');
  const shutdown = $('btn-shutdown-orins');
  if (rebootBody) {
    rebootBody.disabled = commonDisabled || Boolean(bodyPending) || !Boolean(actions.reboot_body?.available);
  }
  if (rebootHead) {
    rebootHead.disabled = commonDisabled || Boolean(headPending) || !Boolean(actions.reboot_head?.available);
  }
  if (recoveryBody) {
    recoveryBody.disabled = commonDisabled || Boolean(bodyPending) || !Boolean(actions.recovery_body?.available);
  }
  if (recoveryHead) {
    recoveryHead.disabled = commonDisabled || Boolean(headPending) || !Boolean(actions.recovery_head?.available);
  }
  if (shutdown) {
    shutdown.disabled = commonDisabled || anyPending || !Boolean(actions.shutdown?.available);
  }

  let message = 'Both Orins are ready. Shutdown powers off the head and body together.';
  if (!headReachable) {
    message = `Head power service is offline: ${head.message || 'unavailable'}`;
  } else if (!Boolean(actions.reboot_body?.available)) {
    message = 'Body power permissions are not installed on bdx-body.';
  } else if (!Boolean(actions.reboot_head?.available)) {
    message = 'Head reboot is unavailable on bdx-head.';
  } else if (!Boolean(actions.recovery_body?.available)) {
    message = 'Body recovery mode is unavailable until the current BDX overlay is installed on bdx-body.';
  } else if (!Boolean(actions.recovery_head?.available)) {
    message = 'Head recovery mode is unavailable until the current BDX overlay is installed on bdx-head.';
  } else if (!Boolean(actions.shutdown?.available)) {
    message = 'Combined shutdown is unavailable until both Orins report power control support.';
  }
  if (policyActive) {
    message = 'A policy is running. Stop it and relax the robot before changing Orin power.';
  }
  if (bodyPending || headPending) {
    const pending = [
      bodyPending ? `body ${bodyPending}` : '',
      headPending ? `head ${headPending}` : '',
    ].filter(Boolean).join(' and ');
    message = `${pending} pending; the connection may disappear shortly.`;
  }
  if (state.system.busy) message = 'Sending Orin power request…';
  setText('system-power-status', message);
}

async function loadSystemStatus() {
  try {
    const response = await api('/api/system');
    state.system.info = response;
    resetSystemActionArm({ preserveStatus: true });
    renderSystemStatus();
    return response;
  } catch (error) {
    state.system.info = {
      body: { host: 'bdx-body', actions: {} },
      head: { host: 'bdx-head', reachable: false, actions: {}, message: error.message },
      actions: {},
    };
    resetSystemActionArm({ preserveStatus: true });
    renderSystemStatus();
    setText('system-power-status', error.message || 'Unable to query Orin power status.');
    return state.system.info;
  }
}

async function requestSystemAction(action) {
  const config = SYSTEM_ACTIONS[action];
  if (!config) throw new Error(`Unknown system action: ${action}`);

  const now = Date.now();
  if (state.system.armedAction !== action || now > state.system.armDeadlineMs) {
    resetSystemActionArm({ preserveStatus: true });
    state.system.armedAction = action;
    state.system.armDeadlineMs = now + 6000;
    const button = $(config.buttonId);
    if (button) {
      button.textContent = config.confirm;
      button.classList.add('power-confirm-armed');
    }
    setText('system-power-status', `Press “${config.confirm}” within six seconds.`);
    state.system.armTimer = setTimeout(() => resetSystemActionArm(), 6000);
    return;
  }

  resetSystemActionArm({ preserveStatus: true });
  state.system.busy = true;
  renderSystemStatus();
  try {
    const response = await api(config.path, { method: 'POST', body: '{}' });
    const current = state.system.info || {};
    const body = { ...(current.body || {}) };
    const head = { ...(current.head || {}) };
    if (action === 'reboot_body') body.pending_action = 'reboot';
    if (action === 'reboot_head') head.pending_action = 'reboot';
    if (action === 'recovery_body') body.pending_action = 'recovery';
    if (action === 'recovery_head') head.pending_action = 'recovery';
    if (action === 'shutdown') {
      body.pending_action = 'shutdown';
      head.pending_action = 'shutdown';
    }
    state.system.info = { ...current, body, head, policy_active: false };
    state.system.busy = false;
    renderSystemStatus();

    let followup = 'The page may disconnect briefly.';
    if (action === 'reboot_body') followup = 'The web service will return after the body reboots.';
    if (action === 'reboot_head') followup = 'Clients using the head access point or USB link will disconnect while it reboots.';
    if (action === 'recovery_body') followup = 'The body will remain offline in NVIDIA Force Recovery Mode until it is flashed or reset.';
    if (action === 'recovery_head') followup = 'The head access point and proxy will remain offline while the head waits in NVIDIA Force Recovery Mode.';
    if (action === 'shutdown') followup = 'Both Orins will power off, both Teensys will enter terminal sleep, and this page will disconnect.';
    setText('system-power-status', `${response.message || config.label + ' scheduled'}. ${followup}`);
    toast(response.message || `${config.label} scheduled`, 5000);
  } catch (error) {
    state.system.busy = false;
    await loadSystemStatus();
    throw error;
  }
}


async function loadMotorsTable() {
  const table = $('motor-registry-table');
  if (!table) return;
  table.innerHTML = '<div class="table-row header motor-id-row"><div>Name</div><div>Default</div><div>ID</div><div>Action</div></div><div class="table-row motor-id-row"><div class="muted">Loading actuators…</div><div></div><div></div><div></div></div>';
  let res;
  try {
    res = await api('/api/motors');
  } catch (error) {
    table.innerHTML = `<div class="table-row header motor-id-row"><div>Name</div><div>Default</div><div>ID</div><div>Action</div></div><div class="table-row motor-id-row"><div class="settings-inline-message" data-tone="error">Unable to load actuators: ${escapeHtml(error.message)}</div><div></div><div></div><div></div></div>`;
    throw error;
  }
  const motors = res.actuators || [];
  const leafCounts = new Map();
  for (const m of motors) {
    const leaf = String(m.name || '').split('.').pop();
    if (leaf) leafCounts.set(leaf, (leafCounts.get(leaf) || 0) + 1);
  }
  const displayName = (name) => {
    const text = String(name || '');
    const leaf = text.split('.').pop();
    return leaf && leafCounts.get(leaf) === 1 ? leaf : text;
  };
  table.innerHTML = '<div class="table-row header motor-id-row"><div>Name</div><div>Default</div><div>ID</div><div>Action</div></div>';
  if (!motors.length) {
    table.insertAdjacentHTML('beforeend', '<div class="table-row motor-id-row"><div class="muted">No actuators reported yet.</div><div></div><div></div><div></div></div>');
    return;
  }
  for (const m of motors) {
    const row = document.createElement('div');
    row.className = 'table-row motor-id-row';
    const safe = String(m.name || '').replace(/[^a-zA-Z0-9_]/g, '-');
    const inputId = `id-${safe}`;
    const defaultId = m.config_id ?? m.motor_id ?? m.registry_id ?? '';
    const idValue = m.registry_override ? m.registry_id : defaultId;
    const rawShortName = displayName(m.name);
    const shortName = displayMotorName(rawShortName);
    const fullNote = rawShortName === m.name ? (m.type || '') : displayMotorName(m.name);
    row.innerHTML = `
      <div class="motor-name-cell" title="${escapeHtml(m.name || '')}"><span>${escapeHtml(shortName)}</span><small>${escapeHtml(fullNote)}</small></div>
      <div>${defaultId === '' || defaultId === null ? '–' : escapeHtml(defaultId)}</div>
      <div><input id="${inputId}" type="number" inputmode="numeric" step="1" value="${escapeHtml(idValue ?? '')}" placeholder="default" /></div>
      <div class="table-actions"><button type="button" data-action="set">Set</button><button type="button" data-action="clear">Clear</button></div>`;
    row.querySelector('[data-action="set"]').onclick = async (ev) => {
      ev.preventDefault();
      try {
        const input = row.querySelector(`#${CSS.escape(inputId)}`);
        const raw = String(input.value || '').trim();
        if (raw === '') {
          await api(`/api/motor-id?name=${encodeURIComponent(m.name)}`, { method: 'DELETE' });
          input.value = defaultId ?? '';
          toast(`cleared ${shortName}`);
          await loadMotorsTable();
          return;
        }
        const val = Number(raw);
        if (!Number.isInteger(val)) throw new Error('motor ID must be an integer');
        if (defaultId !== '' && defaultId !== null && Number(val) === Number(defaultId)) {
          await api(`/api/motor-id?name=${encodeURIComponent(m.name)}`, { method: 'DELETE' });
          input.value = defaultId;
          toast(`${shortName} uses default ID ${defaultId}`);
        } else {
          await api('/api/motor-id', { method: 'POST', body: JSON.stringify({ name: m.name, id: val }) });
          toast(`stored ${shortName} → ${val}`);
        }
        await loadMotorsTable();
      } catch (err) { toast(err.message, 4200); }
    };
    row.querySelector('[data-action="clear"]').onclick = async (ev) => {
      ev.preventDefault();
      try {
        await api(`/api/motor-id?name=${encodeURIComponent(m.name)}`, { method: 'DELETE' });
        row.querySelector(`#${CSS.escape(inputId)}`).value = defaultId ?? '';
        toast(`cleared ${shortName}`);
        await loadMotorsTable();
      } catch (err) { toast(err.message, 4200); }
    };
    table.appendChild(row);
  }
}

function startEvents() {
  state.eventSource?.close?.();
  const source = new EventSource('/events');
  state.eventSource = source;
  source.onmessage = (ev) => {
    if (!ev.data) return;
    try { queuePacket(JSON.parse(ev.data)); } catch (err) { console.warn(err); }
  };
  source.onerror = () => {
    $('status-line').textContent = 'event stream disconnected; retrying…';
    scheduleAuthenticationRecheck();
  };
}

async function bootstrapWebConsole() {
  $('auth-login-form')?.addEventListener('submit', submitAuthentication);
  const authenticated = await loadAuthenticationStatus();
  if (!authenticated) return;
  wireControls();
  const compatible = await checkRuntimeCompatibility();
  if (!compatible) return;
  // Re-enter the selected tab now that API-backed loading is allowed.
  setActiveTab(state.activeTab);
  startEvents();
  startHardwareStatusPolling();
  loadRecordingStatus().catch((error) => console.warn('recording status unavailable', error));
  await initUrdfModel();
  requestAnimationFrame(() => scheduleUrdfModelLoad('startup'));
}

bootstrapWebConsole().catch((error) => {
  const loading = $('auth-loading');
  if (document.body.dataset.authReady !== 'true' && loading) {
    loading.textContent = error.message || 'Unable to initialize browser authentication.';
    return;
  }
  showRuntimeMismatch(error.message);
});
